{"cmd": "python3 - <<'PY'
import csv,json,collections,datetime
F=json.load(open('inputs/fees.json'))
def rm(v,a):
  return v is None or (isinstance(v,list) and (not v or a in v)) or v==a
def bvol(v): return '<100k' if v<100000 else ('100k-1m' if v<=1000000 else ('1m-5m' if v<=5000000 else '>5m'))
def bfra(p): return '<7.2%' if p<.072 else ('7.2%-7.7%' if p<.077 else ('7.7%-8.3%' if p<=.083 else '>8.3%'))
def month(d): return (datetime.date(2023,1,1)+datetime.timedelta(days=d-1)).month
def match(r,a):
 cs,acc,cap,vol,fra,mcc,cr,aci,intra=a
 return r['card_scheme']==cs and rm(r['account_type'],acc) and rm(r['capture_delay'],cap) and rm(r['monthly_volume'],vol) and rm(r['monthly_fraud_level'],fra) and rm(r['merchant_category_code'],mcc) and rm(r['is_credit'],cr) and rm(r['aci'],aci) and rm(r['intracountry'],intra)
stats=collections.defaultdict(lambda:[0.,0.]); txs=[]
with open('inputs/payments.csv',newline='') as f:
 for r in csv.DictReader(f):
  if r['merchant']!='Belles_cookbook_store': continue
  m=month(int(r['day_of_year'])); a=float(r['eur_amount']); stats[m][0]+=a
  if r['has_fraudulent_dispute']=='True': stats[m][1]+=a
  txs.append((m,int(r['day_of_year']),r))
for label,pred in [('Jan10',lambda m,d:d==10),('March',lambda m,d:m==3),('Jan',lambda m,d:m==1)]:
 union=set(); mult=collections.Counter(); pat=collections.Counter()
 for m,d,r in txs:
  if not pred(m,d): continue
  vol,fra=stats[m]; intra=1. if r['issuing_country']==r['acquirer_country'] else 0.
  a=(r['card_scheme'],'R','<3',bvol(vol),bfra(fra/vol),5942,r['is_credit']=='True',r['aci'],intra)
  ids=tuple(x['ID'] for x in F if match(x,a))
  union.update(ids); mult[len(ids)]+=1; pat[ids]+=1
 print('\n',label,'tx',sum(mult.values()),'mult',dict(mult),'union',len(union))
 print('union',sorted(union))
 print('patterns',pat.most_common(30))
